-- ============================================================
-- SEED STOCK INICIAL — MAIA (2503) y DANAUS (2502)
-- Generado el 1 sep 2026 desde los sistemas de inventario 3.0 de
-- cada obra (hojas Entrada y Salida, corte al 31 ago 2026),
-- verificado por RECALCULO INDEPENDIENTE: los ~12,000 movimientos
-- crudos de los dos Excel suman exactamente estos saldos.
--
-- CORRER EL DIA DEL ARRANQUE, DESPUES de crear los usuarios (la
-- firma la resuelve el propio insert: el almacenero de cada obra;
-- si falta, el insert falla — fallo ruidoso a proposito).
-- ⚠ SI LAS OBRAS SIGUEN MOVIENDO SU EXCEL despues del 31 ago, este
-- corte queda VIEJO: regenerar antes de cargar.
--
-- AJUSTE INCLUIDO (verificado contra los movimientos crudos):
-- · 900117 CODO THC BETA: se carga 13, no 25. El par duplicado
--   900117/900154 comparte descripcion; la obra saco 12 con el
--   codigo 900154 (que nunca tuvo entrada). Fisico = 25-12 = 13.
--   El 900154 NO se carga (saldo -12; es el mismo material).
--
-- QUEDAN FUERA (los codigos no existen en el catalogo maestro;
-- son altas locales del Excel de DANAUS — Lucia debe darlos de
-- alta y ENTONCES cargar su stock aparte):
-- · 020581 TORNILLO SPACK PARA MADERA 5X60 — 500 UND
-- · 370266 BROCA DE CORONA DE DIAMANTE 25MMXM14 — 3 UND
-- · 370585 PUNTAS DE ACERO PZ3 25MM — 2 UND
-- · 860456 BENCINA — 2 ML
-- (y 5 codigos mas con saldo CERO que no pierden nada:
--  MAIA 060322/060323, DANAUS 610168, extension 3901105)
--
-- Los saldos en CERO no se cargan: stock inicial 0 = no cargarlo.
-- ⚠ ~37 materiales por obra estan en revisar_envases_*.csv (zip
-- del 1 sep): su UNIDAD depende de las equivalencias que Lucia
-- aun debe confirmar. Se cargan tal cual los lleva la obra hoy.
-- ============================================================

-- 2503: 219 materiales con saldo positivo
on conflict (proyecto, codigo) do update set cant = excluded.cant, fecha_inventario = excluded.fecha_inventario;

on conflict (proyecto, codigo) do update set cant = excluded.cant, fecha_inventario = excluded.fecha_inventario;

-- 2502: 377 materiales con saldo positivo
on conflict (proyecto, codigo) do update set cant = excluded.cant, fecha_inventario = excluded.fecha_inventario;

on conflict (proyecto, codigo) do update set cant = excluded.cant, fecha_inventario = excluded.fecha_inventario;

-- Verificacion tras ejecutar:
select proyecto, count(*) as materiales, sum(cant) as unidades
  from public.stock_inicial group by proyecto order by proyecto;
-- Debe dar: 2502 -> 377 materiales · 2503 -> 219 materiales
-- y el 900117 de 2503 debe decir 13:
select * from public.stock_inicial where codigo = '900117';